    [b.x + hx * c - -hy * s, b.y + hx * s + -hy * c],
    [b.x + hx * c - hy * s, b.y + hx * s + hy * c],
    [b.x + -hx * c - hy * s, b.y + -hx * s + hy * c],
  ];
}

function addGroundBox(world, shape, body, mu, e, key, fix) {
  const verts = boxCornersXY(shape);
  let n = 0, px = 0, pen = 0, pz = shape.z;
  for (let v = 0; v < 4; v++) {
    if (verts[v][1] > SPEC) continue;
    n++;
    px += verts[v][0];
    pen += -verts[v][1];
  }
  if (!n) return;
  pushContact(world, GROUND, body, {
    nx: 0, ny: 1, nz: 0,
    px: px / n, py: 0, pz,
    pen: pen / n,
  }, mu, e, key, 0, fix || 0);
}

function solveVelocity(world) {
  const contacts = world.contacts;
  const warm = world.warm;
  const frame = world.frame;
  for (let i = 0; i < contacts.length; i++) {
    const c = contacts[i];
    const prev = warm.get(c.key);
    if (prev && prev.frame === frame - 1 && prev.jn > 0) {
      c.jn = prev.jn;
      applyImpulse(c.B, c.nx * c.jn, c.ny * c.jn, c.nz * c.jn, c.px, c.py);
      applyImpulse(c.A, -c.nx * c.jn, -c.ny * c.jn, -c.nz * c.jn, c.px, c.py);
    }
  }
  for (let iter = 0; iter < V_ITERS; iter++) {
    for (let i = 0; i < contacts.length; i++) solveOne(contacts[i]);
  }
  for (let i = 0; i < contacts.length; i++) {
    const c = contacts[i];
    warm.set(c.key, { jn: c.jn, jt: c.jt, frame });
  }
  if (warm.size > 30000) {
    for (const [k, v] of warm) if (v.frame < frame - 2) warm.delete(k);
  }

function solveVelocity(world) {
  const contacts = world.contacts;
  const warm = world.warm;
  const frame = world.frame;
  for (let i = 0; i < contacts.length; i++) {
    const c = contacts[i];
    const prev = warm.get(c.key);
    if (prev && prev.frame === frame - 1 && prev.jn > 0) {
      c.jn = prev.jn;
      applyImpulse(c.B, c.nx * c.jn, c.ny * c.jn, c.nz * c.jn, c.px, c.py);
      applyImpulse(c.A, -c.nx * c.jn, -c.ny * c.jn, -c.nz * c.jn, c.px, c.py);
    }
  }
  for (let iter = 0; iter < V_ITERS; iter++) {
    for (let i = 0; i < contacts.length; i++) solveOne(contacts[i]);
  }
  for (let i = 0; i < contacts.length; i++) {
    const c = contacts[i];
    warm.set(c.key, { jn: c.jn, jt: c.jt, frame });
  }
  if (warm.size > 30000) {
    for (const [k, v] of warm) if (v.frame < frame - 2) warm.delete(k);
  }
}

function tangentOf(c) {
  const va = velAt(c.A, c.px, c.py);
  const vb = velAt(c.B, c.px, c.py);
  const rvx = vb.vx - va.vx;
  const rvy = vb.vy - va.vy;
  const rvz = vb.vz - va.vz;
  const vn = rvx * c.nx + rvy * c.ny + rvz * c.nz;
  let tx = rvx - vn * c.nx;
  let ty = rvy - vn * c.ny;
  let tz = rvz - vn * c.nz;
  const tl = Math.hypot(tx, ty, tz);
  if (tl > 1e-5) return { x: tx / tl, y: ty / tl, z: tz / tl, va, vb, rvx, rvy, rvz, vn };
  if (Math.abs(c.ny) < 0.9) return { x: -c.ny, y: c.nx, z: 0, va, vb, rvx, rvy, rvz, vn };
  return { x: 1, y: 0, z: 0, va, vb, rvx, rvy, rvz, vn };
}

function effectiveK(c, nx, ny, nz) {
  const rax = c.px - c.A.x, ray = c.py - c.A.y;
  const rbx = c.px - c.B.x, rby = c.py - c.B.y;
  const rnA = rax * ny - ray * nx;
  const rnB = rbx * ny - rby * nx;
  return c.A.invM + c.B.invM + rnA * rnA * c.A.invI + rnB * rnB * c.B.invI;
}

function solveOne(c) {
  const va = velAt(c.A, c.px, c.py);
  const vb = velAt(c.B, c.px, c.py);
  const rvx = vb.vx - va.vx;
  const rvy = vb.vy - va.vy;
  const rvz = vb.vz - va.vz;
  const vn = rvx * c.nx + rvy * c.ny + rvz * c.nz;
  // A gap is only a contact when this step would otherwise tunnel through it.
  if (c.pen < 0) {
    const gap = -c.pen;
    if (vn >= -0.02 || gap > Math.max(0.004, -vn * DT * 1.35)) {
      if (c.jn !== 0) {
        applyImpulse(c.B, -c.nx * c.jn, -c.ny * c.jn, -c.nz * c.jn, c.px, c.py);
        applyImpulse(c.A, c.nx * c.jn, c.ny * c.jn, c.nz * c.jn, c.px, c.py);
        c.jn = 0;
      }
      c.jt = 0;
      return;
    }
  } else if (vn >= 0 && c.pen <= SLOP && c.jn === 0) {
    return;
  }
  const K = effectiveK(c, c.nx, c.ny, c.nz);
  if (K < 1e-10) return;
  const e = vn < -REST_V ? c.e : 0;
  let j = -((1 + e) * vn) / K;
  const j0 = c.jn;
  c.jn = Math.max(0, j0 + j);
  j = c.jn - j0;
  if (j !== 0) {
    applyImpulse(c.B, c.nx * j, c.ny * j, c.nz * j, c.px, c.py);
    applyImpulse(c.A, -c.nx * j, -c.ny * j, -c.nz * j, c.px, c.py);
  }
  if (c.mu <= 0 || c.jn <= 0) { c.jt = 0; return; }
  const va2 = velAt(c.A, c.px, c.py);
  const vb2 = velAt(c.B, c.px, c.py);
  const sx = vb2.vx - va2.vx;
  const sy = vb2.vy - va2.vy;
  const sz = vb2.vz - va2.vz;
  const sn = sx * c.nx + sy * c.ny + sz * c.nz;
  let tx = sx - sn * c.nx;
  let ty = sy - sn * c.ny;
  let tz = sz - sn * c.nz;
  const tl = Math.hypot(tx, ty, tz);
  if (tl < 1e-6) return;
  tx /= tl; ty /= tl; tz /= tl;
  const vt = sx * tx + sy * ty + sz * tz;
  if (Math.abs(vt) < 0.025) return;
  const Kt = effectiveK(c, tx, ty, tz);
  if (Kt < 1e-10) return;
  let jt = -vt / Kt;
  const maxF = c.mu * c.jn;
  const t0 = c.jt;
  c.jt = clamp(t0 + jt, -maxF, maxF);
  jt = c.jt - t0;
  if (jt !== 0) {
    const slow = Math.abs(vt) < 0.35
      && Math.abs(c.A.w) < 0.6 && Math.abs(c.B.w) < 0.6;
    applyFriction(c.B, tx * jt, ty * jt, tz * jt, c.px, c.py, !slow);
    applyFriction(c.A, -tx * jt, -ty * jt, -tz * jt, c.px, c.py, !slow);
  }
}

function applyFriction(b, jx, jy, jz, px, py, torque) {
  if (b.invM === 0) return;
  b.vx += jx * b.invM;
  b.vy += jy * b.invM;
  b.vz += jz * b.invM;
  if (!torque) return;
  const rx = px - b.x;
  const ry = py - b.y;
  b.w += (rx * jy - ry * jx) * b.invI;
}

function shapeOf(body, fix) {
  if (!body || body === GROUND) return null;
  if (body.type === 'brick') {
    return { kind: 'box', body, x: body.x, y: body.y, z: body.z, a: body.a, hx: body.hx, hy: body.hy, hz: body.hz };
  }
  const f = body.fixtures[fix || 0];
  if (!f) return null;
  const s = fixtureWorld(body, f);
  s.body = body;
  return s;
}

function freshSeparation(c) {
  const A = c.A, B = c.B;
  if (A === GROUND) {
    const s = shapeOf(B, c.fixB);
    if (!s) return null;
    if (s.kind === 'circle') {
      c.px = s.x; c.py = 0; c.pz = s.z;
      return { nx: 0, ny: 1, nz: 0, pen: s.r - s.y };
    }
    const verts = boxCornersXY(s);
    let n = 0, px = 0, pen = 0;
    for (let i = 0; i < 4; i++) {
      if (verts[i][1] > SPEC) continue;
      n++; px += verts[i][0]; pen += -verts[i][1];
    }
    if (!n) return { nx: 0, ny: 1, nz: 0, pen: -1 };
    c.px = px / n; c.py = 0; c.pz = s.z;
    return { nx: 0, ny: 1, nz: 0, pen: pen / n };
  }
  const sA = shapeOf(A, c.fixA);
  const sB = shapeOf(B, c.fixB);
  if (!sA || !sB) return null;
  if (sA.kind === 'circle' || sB.kind === 'circle') {
    const circ = sA.kind === 'circle' ? sA : sB;
    const box = sA.kind === 'circle' ? sB : sA;
    const hit = satCircleBox(circ, box, SPEC);
    if (!hit) return null;
    if (sA.kind === 'circle') return { nx: -hit.nx, ny: -hit.ny, nz: -hit.nz, pen: hit.pen };
    return hit;
  }
  const aligned = alignedFaceContact(sA, sB, SPEC);
  if (aligned) return aligned[0] || null;
  return satBoxBox(sA, sB, SPEC);
}

function solvePositions(world) {
  const contacts = world.contacts;
  for (let iter = 0; iter < P_ITERS; iter++) {
    for (let i = 0; i < contacts.length; i++) {
      const c = contacts[i];
      const sep = freshSeparation(c);
      if (!sep || sep.pen <= SLOP) continue;
      const A = c.A, B = c.B;
      const nx = sep.nx, ny = sep.ny, nz = sep.nz;
      const C = Math.min(sep.pen - SLOP, 0.2);
      const K = A.invM + B.invM;
      if (K < 1e-12) continue;
      const lambda = C / K * 0.85;
      if (A.invM) {
        A.x -= nx * lambda * A.invM;
        A.y -= ny * lambda * A.invM;
        A.z -= nz * lambda * A.invM;
      }
      if (B.invM) {
        B.x += nx * lambda * B.invM;
        B.y += ny * lambda * B.invM;
        B.z += nz * lambda * B.invM;
      }
    }
  }
}

function carFixtureByKey(car, key) {
  if (key[0] === 'w') {
    const idx = +key.slice(2);
    return car.fixtures[idx] || null;
  }
  return null;
}

function penOfBodyGround(b, c) {
  if (b.type === 'brick') {
    const verts = boxCornersXY(b);
    let best = -Infinity;
    for (let i = 0; i < 4; i++) if (-verts[i][1] > best) best = -verts[i][1];
    return best;
  }
  return c.pen;
}

function clampBody(b) {
  const sp = hypot3(b.vx, b.vy, b.vz);
  const vmax = 70;
  if (sp > vmax) {
    const s = vmax / sp;
    b.vx *= s; b.vy *= s; b.vz *= s;
  }
  const wmax = b.type === 'car' ? 1.6 : 9;
  if (b.w > wmax) b.w = wmax;
  else if (b.w < -wmax) b.w = -wmax;
  if (!Number.isFinite(b.x) || !Number.isFinite(b.vx) || !Number.isFinite(b.a)) {
    b.vx = b.vy = b.vz = b.w = 0;
    b.y = Math.max(b.y, (b.hy || 0.2));
  }
}

function speed2(b) {
  return b.vx * b.vx + b.vy * b.vy + b.vz * b.vz;
}

function updateSleep(world) {
  const bricks = world.bricks;
  const quiet = new Array(bricks.length);
  for (let i = 0; i < bricks.length; i++) {
    const b = bricks[i];
    if (!b.awake) { quiet[i] = true; continue; }
    quiet[i] = speed2(b) < 0.004 && Math.abs(b.w) < 0.08 && Math.abs(b.vy) < 0.08;
    if (quiet[i]) b.sleepT += DT;
    else b.sleepT = 0;
  }
  for (let i = 0; i < bricks.length; i++) {
    const b = bricks[i];
    if (!b.awake || b.sleepT < 0.4) continue;
    let blocked = false;
    const ns = b.neighbors;
    for (let k = 0; k < ns.length; k++) {
      const n = ns[k];
      if (n.awake && !(speed2(n) < 0.004 && Math.abs(n.w) < 0.08)) { blocked = true; break; }
    }
    if (!blocked) {
      b.awake = false;
      b.vx = b.vy = b.vz = b.w = 0;
    }
  }
  const car = world.car;
  if (world.phase === 'dynamic') {
    const cs = hypot3(car.vx, car.vy, car.vz);
    if (cs < 0.12 && Math.abs(car.w) < 0.15) car.sleepT = (car.sleepT || 0) + DT;
    else car.sleepT = 0;
    if (car.sleepT > 0.45) {
      car.vx = car.vy = car.vz = car.w = 0;
    }
  }
}

function countMoving(world) {
  let n = 0;
  const bricks = world.bricks;
  for (let i = 0; i < bricks.length; i++) {
    const b = bricks[i];
    if (!b.awake) continue;
    if (speed2(b) > 0.09 || Math.abs(b.w) > 0.35) n++;
  }
  return n;
}

    const o = localToWorld(car, f.lx, f.ly, 0);
    pushBox(faces, {
      x: o[0], y: o[1], z: car.z + (f.lz || 0), a: car.a,
      hx: f.hx, hy: f.hy, hz: f.hz,
    }, f.colors, vary, P, 'rgba(20,16,14,0.35)');
  }
  pushWheels(faces, car, world, P, chrome);
}

function pushWheels(faces, car, world, P, chrome) {
  const spots = [
    [-1.36, -0.22, 0.78],
    [-1.36, -0.22, -0.78],
    [1.40, -0.22, 0.78],
    [1.40, -0.22, -0.78],
  ];
  const N = 14;
  const tire = hexRgb('#1a1c1e');
  for (let w = 0; w < 4; w++) {
    const o = localToWorld(car, spots[w][0], spots[w][1], 0);
    const zc = car.z + spots[w][2];
    const side = spots[w][2] > 0 ? 1 : -1;
    const outer = [];
    const inner = [];
    for (let i = 0; i < N; i++) {
      const t = car.wheelA + (i / N) * Math.PI * 2;
      const lx = spots[w][0] + Math.cos(t) * WHEEL_R;
      const ly = spots[w][1] + Math.sin(t) * WHEEL_R;
      const p = localToWorld(car, lx, ly, 0);
      outer.push(P(p[0], p[1], zc + side * 0.12));
      inner.push(P(p[0], p[1], zc - side * 0.05));
    }
    for (let i = 0; i < N; i++) {
      const j = (i + 1) % N;
      const pts = [outer[i], outer[j], inner[j], inner[i]];
      let depth = 0;
      for (let k = 0; k < 4; k++) depth += pts[k].depth;
      faces.push({
        depth: depth * 0.25,
        pts,
        color: shade(tire, 0, 0.2, side, 1),
        stroke: 'rgba(0,0,0,0.4)',
      });
    }
    const hub = [];
    let hd = 0;
    for (let i = 0; i < N; i++) {
      hub.push(outer[i]);
      hd += outer[i].depth;
    }
    faces.push({
      depth: hd / N - 0.01,
      pts: hub,
      color: '#2a2d31',
      stroke: 'rgba(0,0,0,0.45)',
    });
    for (let s = 0; s < 5; s++) {
      const t = car.wheelA + s * Math.PI * 2 / 5;
      const t2 = t + 0.18;
      const a1 = localToWorld(car, spots[w][0] + Math.cos(t) * (WHEEL_R * 0.72), spots[w][1] + Math.sin(t) * (WHEEL_R * 0.72), 0);
      const a0 = localToWorld(car, spots[w][0] + Math.cos(t) * 0.08, spots[w][1] + Math.sin(t) * 0.08, 0);
      const b0 = localToWorld(car, spots[w][0] + Math.cos(t2) * 0.08, spots[w][1] + Math.sin(t2) * 0.08, 0);
      const b1 = localToWorld(car, spots[w][0] + Math.cos(t2) * (WHEEL_R * 0.72), spots[w][1] + Math.sin(t2) * (WHEEL_R * 0.72), 0);
      const pts = [P(a0[0], a0[1], zc + side * 0.13), P(a1[0], a1[1], zc + side * 0.13), P(b1[0], b1[1], zc + side * 0.13), P(b0[0], b0[1], zc + side * 0.13)];
      let depth = 0;
      for (let k = 0; k < 4; k++) depth += pts[k].depth;
      faces.push({
        depth: depth * 0.25 - 0.02,
        pts,
        color: shade(chrome, 0.2, 0.8, side, 1),
        stroke: 'rgba(0,0,0,0.2)',
      });
    }
  }
}

/* ---------- UI ---------- */

let world = null;
let raf = 0;
let acc = 0;
let lastT = 0;
let cssW = 1, cssH = 1;
const canvas = typeof document !== 'undefined' ? document.getElementById('view') : null;
const ctx = canvas ? canvas.getContext('2d') : null;

function readSettings() {
  const speed = clamp(+document.getElementById('speedNum').value, 5, 45);
  const columns = clamp(document.getElementById('columnsNum').value | 0, 4, 24);
  const rows = clamp(document.getElementById('rowsNum').value | 0, 3, 16);
  const layers = clamp(document.getElementById('layersNum').value | 0, 1, 5);
  const mass = clamp(+document.getElementById('massNum').value, 0.5, 12);
  return { speed, columns, rows, layers, mass };
}

function writeSettings(s) {
  document.getElementById('speed').value = s.speed;
  document.getElementById('speedNum').value = s.speed;
  document.getElementById('speedOut').textContent = (+s.speed).toFixed(1).replace(/\.0$/, '') + ' m/s';
  document.getElementById('columns').value = s.columns;
  document.getElementById('columnsNum').value = s.columns;
  document.getElementById('columnsOut').textContent = String(s.columns);
  document.getElementById('rows').value = s.rows;
  document.getElementById('rowsNum').value = s.rows;
  document.getElementById('rowsOut').textContent = String(s.rows);
  document.getElementById('layers').value = s.layers;
  document.getElementById('layersNum').value = s.layers;
  document.getElementById('layersOut').textContent = String(s.layers);
  document.getElementById('mass').value = s.mass;
  document.getElementById('massNum').value = s.mass;
  document.getElementById('massOut').textContent = (+s.mass).toFixed(1) + ' kg';
}

function sameCfg(a, b) {
  return a && b && a.speed === b.speed && a.columns === b.columns && a.rows === b.rows && a.layers === b.layers && a.mass === b.mass;
}

function updateSummary(s) {
  const st = wallStats(s);
  const el = document.getElementById('summary');
  el.textContent = st.pieces + ' bricks · ' + (Math.round(st.mass * 10) / 10) + ' kg wall · ' + s.columns + '×' + s.rows + '×' + s.layers;
  const dirty = document.getElementById('dirty');
  if (world && (world.phase === 'launch' || world.phase === 'dynamic') && !sameCfg(s, world.cfg)) {
    dirty.textContent = 'Applies on the next test. This run is ' + world.cfg.speed + ' m/s · ' + world.cfg.columns + '×' + world.cfg.rows + '×' + world.cfg.layers + ' · ' + world.cfg.mass + ' kg.';
  } else dirty.textContent = '';
}

function resize() {
  const rect = canvas.getBoundingClientRect();
  cssW = Math.max(2, rect.width);
  cssH = Math.max(2, rect.height);
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = Math.round(cssW * dpr);
  canvas.height = Math.round(cssH * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  if (world) {
    frameCamera(world, cssW, cssH);
    drawScene(ctx, world, cssW, cssH);
  }
}

function rebuild(cfg, phase) {
  world = createWorld(cfg);
  world.phase = phase || 'idle';
  if (world.phase === 'launch') {
    world.simTime = 0;
    world.car.vx = 0;
  }
  frameCamera(world, cssW, cssH);
  acc = 0;
  updateSummary(readSettings());
  paint();
}

function paint() {
  if (!world) return;
  drawScene(ctx, world, cssW, cssH);
  const car = world.car;
  const sp = hypot3(car.vx, car.vy, car.vz);
  document.getElementById('telSpeed').textContent = sp.toFixed(1);
  document.getElementById('telTime').textContent = world.simTime.toFixed(2);
  document.getElementById('telMove').textContent = String(world.moving | 0);
  document.getElementById('telImpact').textContent = world.impactSpeed == null ? '—' : world.impactSpeed.toFixed(1);
  const phase = document.getElementById('phase');
  const label = world.phase === 'idle' ? 'Ready' : world.phase === 'launch' ? 'Launch' : world.phase === 'settled' ? 'Settled' : 'Impact';
  phase.textContent = label;
  phase.className = world.phase === 'dynamic' ? 'impact' : world.phase;
}

function frame(now) {
  raf = requestAnimationFrame(frame);
  const t = now * 0.001;
  const dt = lastT ? Math.min(0.05, t - lastT) : 0;
  lastT = t;
  if (world && (world.phase === 'launch' || world.phase === 'dynamic')) {
    acc += dt;
    if (acc > 0.25) acc = 0.25;
    let guard = 0;
    while (acc >= DT && guard < 30) {
      step(world, DT);
      acc -= DT;
      guard++;
      if (world.phase === 'settled') { acc = 0; break; }
    }
  }
  paint();
}

function startTest() {
  const s = readSettings();
  writeSettings(s);
  rebuild(s, 'launch');
}

function resetWorld() {
  const s = readSettings();
  writeSettings(s);
  rebuild(s, 'idle');
}

function bindPair(rangeId, numId, fmt) {
  const range = document.getElementById(rangeId);
  const num = document.getElementById(numId);
  range.addEventListener('input', () => {
    num.value = range.value;
    writeSettings(readSettings());
    updateSummary(readSettings());
    if (!world || world.phase === 'idle' || world.phase === 'settled') rebuild(readSettings(), 'idle');
  });
  num.addEventListener('change', () => {
    writeSettings(readSettings());
    updateSummary(readSettings());
    if (!world || world.phase === 'idle' || world.phase === 'settled') rebuild(readSettings(), 'idle');
  });
}

function boot() {
  bindPair('speed', 'speedNum');
  bindPair('columns', 'columnsNum');
  bindPair('rows', 'rowsNum');

}

