const fs = require('fs'), vm = require('vm');
const html = fs.readFileSync('index.html', 'utf8');
if (!html.startsWith('<!DOCTYPE html>') || !html.trimEnd().endsWith('</html>')) {
  console.error('HTML envelope bad');
  process.exit(1);
}
const src = html.slice(html.indexOf('<script>') + 8, html.lastIndexOf('</script>'));
vm.runInThisContext(src);
const L = globalThis.__crashlab;
const D = L.DEFAULTS;

function displaced(w) {
  let n = 0, far = 0;
  for (const b of w.bricks) {
    const moved = Math.hypot(b.vx, b.vy, b.vz) > 0.4 || Math.abs(b.a) > 0.2 || b.y < b.hy * 0.5;
    if (b.awake && (Math.hypot(b.vx, b.vy, b.vz) > 0.3 || Math.abs(b.a) > 0.15)) n++;
    if (b.x > L.WALL_FRONT + 1.2 || b.y < 0.05) far++;
  }
  return { moving: n, far };
}

function run(cfg, seconds) {
  const w = L.createWorld(cfg);
  w.phase = 'launch';
  const n = Math.round(seconds / L.DT);
  const t0 = Date.now();
  let nan = false;
  let maxAwake = 0;
  for (let i = 0; i < n; i++) {
    L.step(w, L.DT);
    if ((i + 1) % 120 === 0) {
      let awake = 0;
      for (const b of w.bricks) if (b.awake) awake++;
      if (awake > maxAwake) maxAwake = awake;
    }
    if (!Number.isFinite(w.car.x)) { nan = true; break; }
  }
  let awake = 0, bad = 0;
  for (const b of w.bricks) {
    if (b.awake) awake++;
    if (!Number.isFinite(b.x + b.y + b.z + b.a + b.vx)) bad++;
  }
  const d = displaced(w);
  return {
    ms: Date.now() - t0,
    phase: w.phase,
    sim: +w.simTime.toFixed(3),
    carX: +w.car.x.toFixed(3),
    carV: +w.car.vx.toFixed(3),
    bricks: w.bricks.length,
    awake, maxAwake,
    moving: w.moving,
    far: d.far,
    pen: +w.stats.maxPen.toFixed(4),
    nan: nan || bad > 0,
    snap: L.snapshotPhysics(w),
  };
}

function idle() {
  const w = L.createWorld(D);
  w.phase = 'dynamic';
  w.car.x = -80; w.car.vx = 0; w.car.sleepT = 2;
  const start = w.bricks.map(b => [b.x, b.y, b.z, b.a]);
  for (let i = 0; i < 240; i++) L.step(w, L.DT);
  let drift = 0, awake = 0;
  for (let i = 0; i < w.bricks.length; i++) {
    const b = w.bricks[i];
    if (b.awake) awake++;
    drift = Math.max(drift, Math.hypot(b.x - start[i][0], b.y - start[i][1], b.z - start[i][2], b.a - start[i][3]));
  }
  return { drift: +drift.toFixed(5), awake, bricks: w.bricks.length };
}

