const fs = require('fs'), vm = require('vm');
const html = fs.readFileSync('index.html', 'utf8');
const src = html.slice(html.indexOf('<script>') + 8, html.lastIndexOf('</script>'));
vm.runInThisContext(src);
const L = globalThis.__crashlab;
const D = L.DEFAULTS;
const RUNWAY = 7.5;

function afterImpact(cfg, extra) {
  const launch = (2 * RUNWAY) / cfg.speed;
  const w = L.createWorld(cfg);
  w.phase = 'launch';
  const n = Math.round((launch + extra) / L.DT);
  const t0 = Date.now();
  let nan = false;
  let maxAwake = 0;
  let minCarV = Infinity;
  for (let i = 0; i < n; i++) {
    L.step(w, L.DT);
    if (!Number.isFinite(w.car.x + w.car.vx)) { nan = true; break; }
    if (w.phase === 'dynamic') {
      if (w.car.vx < minCarV) minCarV = w.car.vx;
      if ((i & 63) === 0) {
        let awake = 0;
        for (const b of w.bricks) if (b.awake) awake++;
        if (awake > maxAwake) maxAwake = awake;
      }
    }
  }
  let awake = 0, tossed = 0, standing = 0;
  for (const b of w.bricks) {
    if (!Number.isFinite(b.x + b.y + b.z + b.vx + b.a)) nan = true;
    if (b.awake) awake++;
    const shifted = Math.abs(b.x - (b.layer != null ? 0 : 0)) ;
    if (b.y > b.hy + 0.05 && Math.abs(b.a) < 0.35 && Math.abs(b.x - (L.WALL_FRONT + (b.layer + 0.5) * 0.25)) < 0.2) standing++;
    if (b.x > L.WALL_FRONT + 1.5 || b.y > 2.4 || Math.hypot(b.x - L.WALL_FRONT, b.z) > 4.2 && b.y < 1) tossed++;
  }
  return {
    ms: Date.now() - t0,
    phase: w.phase,
    sim: +w.simTime.toFixed(2),
    carX: +w.car.x.toFixed(2),
    carV: +w.car.vx.toFixed(2),
    minCarV: +minCarV.toFixed(2),
    bricks: w.bricks.length,
    awake, maxAwake, standing, tossed,
    moving: w.moving,
    pen: +w.stats.maxPen.toFixed(3),
    nan,
    snap: L.snapshotPhysics(w),
  };
}

