const fs = require('fs'), vm = require('vm');
const html = fs.readFileSync('index.html', 'utf8');
const src = html.slice(html.indexOf('<script>') + 8, html.lastIndexOf('</script>'));
vm.runInThisContext(src);
const L = globalThis.__crashlab;
const D = L.DEFAULTS;
const RUNWAY = 7.5;

function afterImpact(cfg, extra) {
  const launch = (2 * RUNWAY) / cfg.speed;
  const w = L.createWorld(cfg);
  w.phase = 'launch';
  const n = Math.round((launch + extra) / L.DT);
  const t0 = Date.now();
  let nan = false;
  let maxAwake = 0;
  let minCarV = Infinity;
  for (let i = 0; i < n; i++) {
    L.step(w, L.DT);
    if (!Number.isFinite(w.car.x + w.car.vx)) { nan = true; break; }
    if (w.phase === 'dynamic') {
      if (w.car.vx < minCarV) minCarV = w.car.vx;
      if ((i & 63) === 0) {
        let awake = 0;
        for (const b of w.bricks) if (b.awake) awake++;
        if (awake > maxAwake) maxAwake = awake;
      }
    }
  }
  let awake = 0, tossed = 0, standing = 0;
  for (const b of w.bricks) {
    if (!Number.isFinite(b.x + b.y + b.z + b.vx + b.a)) nan = true;
    if (b.awake) awake++;
    const shifted = Math.abs(b.x - (b.layer != null ? 0 : 0)) ;
    if (b.y > b.hy + 0.05 && Math.abs(b.a) < 0.35 && Math.abs(b.x - (L.WALL_FRONT + (b.layer + 0.5) * 0.25)) < 0.2) standing++;
    if (b.x > L.WALL_FRONT + 1.5 || b.y > 2.4 || Math.hypot(b.x - L.WALL_FRONT, b.z) > 4.2 && b.y < 1) tossed++;
  }
  return {
    ms: Date.now() - t0,
    phase: w.phase,
    sim: +w.simTime.toFixed(2),
    carX: +w.car.x.toFixed(2),
    carV: +w.car.vx.toFixed(2),
    minCarV: +minCarV.toFixed(2),
    bricks: w.bricks.length,
    awake, maxAwake, standing, tossed,
    moving: w.moving,
    pen: +w.stats.maxPen.toFixed(3),
    nan,
    snap: L.snapshotPhysics(w),
  };
}

function show(label, r) {
  const { snap, ...rest } = r;
  console.log(label, JSON.stringify(rest));
  return r;
}

const a = show('default+1.2', afterImpact(D, 1.2));
const b = afterImpact(D, 1.2);
let same = a.snap.length === b.snap.length;
for (let i = 0; i < a.snap.length && same; i++) if (a.snap[i] !== b.snap[i]) same = false;
console.log('deterministic', same);
const slow = show('slow5+1.2', afterImpact({ ...D, speed: 5 }, 1.2));
const fast = show('fast45+0.8', afterImpact({ ...D, speed: 45 }, 0.8));
const heavy = show('heavy12+1.2', afterImpact({ ...D, mass: 12 }, 1.2));
const light = show('light+0.8', afterImpact({ ...D, mass: 0.5 }, 0.8));
const small = show('minwall+0.8', afterImpact({ ...D, columns: 4, rows: 3, layers: 1 }, 0.8));
const big = show('maxwall+0.35', afterImpact({ ...D, columns: 24, rows: 16, layers: 5, speed: 22 }, 0.35));

const ok = same && !a.nan && !slow.nan && !fast.nan && !heavy.nan && !light.nan && !small.nan && !big.nan
  && a.carV < 18
  && heavy.carV < light.carV
  && slow.standing > fast.standing
  && fast.carX > slow.carX
  && big.pen < 1.5;
console.log(ok ? 'CHECK_OK' : 'CHECK_FAIL');
process.exit(ok ? 0 : 2);
